      /* GENERIQUE / BNP */
      html {
        -ms-text-size-adjust: 100%;
        -webkit-text-size-adjust: 100%;
        font-size: 15px;
        font-family: hello_typeregular, Arial, sans-serif;
        -webkit-font-smoothing: antialiased;
        color: #424242;
      }

      body {
        font-family: helloType, arial, sans-serif;
        max-width: 1440px;
        margin-right: auto;
        margin-left: auto;
        color: #4e5152
      }

      article,
      aside,
      details,
      figcaption,
      figure,
      footer,
      header,
      hgroup,
      main,
      nav,
      section,
      summary {
        display: block;
      }

      *,
      :after,
      :before {
        -webkit-box-sizing: border-box;
        -moz-box-sizing: border-box;
        box-sizing: border-box;
      }

      .text-hide {
        font: 0/0 a;
        color: transparent;
        text-shadow: none;
        background-color: transparent;
        border: 0;
      }

      ul li {
        list-style: none;
      }

      a {
        background: 0 0;
      }

      p {
        font-weight: 300;
      }

      .link,
      a:active,
      a:hover,
      a:link,
      a:visited {
        color: #11bad5;
      }

      .icon {
        width: 0;
        height: 0;
        speak: none;
        font-family: iconbnp;
        font-style: normal;
        font-weight: 400;
        font-variant: normal;
        text-transform: none;
        line-height: 1;
        background-image: none;
        -webkit-font-smoothing: antialiased;
        -moz-osx-font-smoothing: grayscale;
        display: inline;
      }

      .hidden {
        display: none !important;
      }

      .pull-left {
        float: left;
      }

      .pull-right {
        float: right;
      }

      #ls-canvas {
        width: 100%;
        max-width: 1400px;
        margin: 0 auto;
        background-color: #FFF;
        position: relative;
      }

      [class*=col-] {
        float: left;
      }

      .col-10 {
        width: 10%;
      }

      .col-40 {
        width: 40%;
      }

      .col-50 {
        width: 50%;
      }

      .container {
        width: 1024px;
        margin-right: auto;
        margin-left: auto;
      }

      .container-ident {
        position: relative;
        width: 100%;
        margin: 0 auto;
        padding: 1rem;
        padding-top: 4rem;
        padding-bottom: 12rem;
      }

      .btn {
        font-size: 12px;
        padding: 14px 30px;
        border-radius: 50px;
        display: inline-block;
        -ms-touch-action: manipulation;
        touch-action: manipulation;
        cursor: pointer;
        background-image: none;
        white-space: nowrap;
        text-transform: uppercase;
        color: #fff;
        text-align: center;
        font-weight: 700;
        -webkit-box-shadow: 0 3px 6px 0 rgba(31, 39, 42, .18);
        box-shadow: 0 3px 6px 0 rgba(31, 39, 42, .18);
        letter-spacing: .3px;
        line-height: 1;
        position: relative;
      }

      #message-erreur {
        display: none;
        margin: 1rem 2rem;
        padding: 1.5rem 7rem 1.5rem 1rem;
        color: #ffffff;
        background-color: #ff5a64;
        border-radius: .3rem;
        border: solid 1px #ccc;
        position: relative;
      }

      .txt-center {
        text-align: center;
      }


















      body.hello-ident.ident {
        background-color: #00577B;
        background-image:
          /*savepage-url=/rsc/contrib/identification/src/themes/hellobank/images/content/bg-header.png*/
          var(--savepage-url-10);
        background-repeat: no-repeat;
        background-size: cover;
        background-position: top 2% center;
      }

      body.hello-ident.ident header {
        padding: 1rem;
        padding-left: 0;
        padding-top: 26px;
      }

      body.hello-ident.ident header img {
        vertical-align: middle;
      }


      body.hello-ident.ident header a {
        float: right;
        margin-top: 2rem;
        color: #FFF;
        border: 1px solid white;
        background: none;
        background-color: transparent;
        -webkit-box-shadow: none;
        box-shadow: none;
      }



      /* CONTENT */
      body.hello-ident.ident #id_balise_div_ident {
        min-height: 700px;
        width: 100%;
        margin: 0 auto;
        padding: 2rem 0 0;
        background-color: transparent !important;
        float: left;
      }

      body.hello-ident.ident #ia-identification .ident.ident {
        max-width: 1024px;
        margin: 0 auto;
      }

      body.hello-ident.ident #ia-identification .ident .main-content {
        width: 55%;
        background-color: #f7f7f7;
        margin-right: 1rem;
        display: inline-block;
        float: left;
        color: #fff;
        border-radius: 0.5rem;
        -webkit-box-shadow: 0px 10px 20px 3px rgba(100, 100, 100, 0.2);
        box-shadow: 0px 10px 20px 3px rgba(100, 100, 100, 0.2);
      }

      body.hello-ident.ident #ia-identification .ident .main-content .container-ident h2 {
        display: none !important;
      }

      body.hello-ident.ident #ia-identification .ident .main-content .container-ident #logincanalnet {
        width: 80%;
        margin: auto;
      }

      body.hello-ident.ident #ia-identification .ident .main-content .container-ident #logincanalnet .grille-ident {
        width: 100%;
        list-style: none;
        padding: 0;
        margin: 0;
      }

      body.hello-ident.ident #ia-identification .ident .main-content .container-ident #logincanalnet .grille-ident li {
        position: relative;
        margin-bottom: 1.5rem;
      }

      body.hello-ident.ident #ia-identification .ident .main-content .container-ident #logincanalnet .grille-ident li a.reset-input {
        background:
          /*savepage-url=/rsc/contrib/identification/src/themes/hellobank/images/content/sprite-form.png*/
          var(--savepage-url-12) center 150px;
        display: block;
        position: absolute;
        top: 22px;
        right: 10px;
        z-index: 1;
        width: 38px;
        height: 42px;
        cursor: pointer;
      }


      body.hello-ident.ident #ia-identification .ident .main-content .container-ident #logincanalnet .grille-ident li label {
        display: block;
        font-size: 11px;
        line-height: 1rem;
        font-weight: normal;
        color: #1f272a;
        margin: 10px 0 2px 0;
        text-transform: uppercase;
        position: relative;
      }

      body.hello-ident.ident #ia-identification .ident .main-content .container-ident #logincanalnet .grille-ident li input {
        background-color: #ffffff;
        background-image: none;
        border-radius: 3px;
        border: 1px solid #dde2e8;
        color: #1f272a;
        display: block;
        font-weight: normal;
        font-size: 0.93333rem;
        height: 52px;
        padding: 6px 45px 6px 1rem;
        width: 100%;
        margin-bottom: 1rem;
      }

      body.hello-ident.ident #ia-identification .ident .main-content .container-ident #logincanalnet .grille-ident li a.form-control {
        background:
          /*savepage-url=/rsc/contrib/identification/src/themes/hellobank/images/content/sprite-form.png*/
          var(--savepage-url-12) center 150px;
        display: block;
        position: absolute;
        top: 1.5rem;
        right: 10px;
        z-index: 1;
        width: 38px;
        height: 42px;
        cursor: pointer;
      }

      body.hello-ident.ident #ia-identification .ident .main-content .container-ident #logincanalnet .grille-ident li #memoriser {
        position: absolute;
        left: -9999px;
      }

      body.hello-ident.ident #ia-identification .ident .main-content .container-ident #logincanalnet .grille-ident li .checkbox-inline {
        text-transform: uppercase;
      }



      body.hello-ident.ident #ia-identification .ident .main-content .container-ident #logincanalnet .grille-ident li [type="checkbox"]:not(:checked)+label {
        position: relative;
        font-size: 13px;
        padding-left: 2rem;
        cursor: pointer;
        margin-bottom: 13px;
        line-height: 1.5rem;
      }

      body.hello-ident.ident #ia-identification .ident .main-content .container-ident #logincanalnet .grille-ident li [type="checkbox"]+label:before {
        content: '';
        height: 1.6rem;
        width: 1.6rem;
        background-color: #fff;
        border: solid 1px #dde2e8;
        position: absolute;
        top: 0;
        left: 0;
        border-radius: 3px;
      }

      body.hello-ident.ident #ia-identification .ident .main-content .container-ident #logincanalnet .grille-ident li [type="checkbox"]:checked+label {
        font-size: 13px;
        line-height: 22px;
        padding-left: 30px;
      }

      body.hello-ident.ident #ia-identification .ident .main-content .container-ident #logincanalnet .grille-ident li [type="checkbox"]:checked+label:before {
        border: solid 1px #11bad5;
      }

      body.hello-ident.ident #ia-identification .ident .main-content .container-ident #logincanalnet .grille-ident li [type="checkbox"]:checked+label:after {
        position: absolute;
        text-align: center;
        content: "";
        font-family: hbicons;
        color: #11bad5;
        font-size: 0.6rem;
        font-weight: bold;
        width: 1.2rem;
        height: 1.2rem;
        left: 4px;
        top: 1px;
      }

      body.hello-ident.ident #ia-identification .ident .main-content .container-ident #logincanalnet .grille-ident li .cell-grid {
        height: 125px;
        margin: 3rem 0;
      }

      body.hello-ident.ident #ia-identification .ident .main-content .container-ident #logincanalnet .grille-ident li .cell-grid #secret-nbr-keyboard {
        background-repeat: no-repeat;
        background-size: 100%;
        height: 170%;
        width: 100%;
      }

      body.hello-ident.ident #ia-identification .ident .main-content .container-ident #logincanalnet .grille-ident li .cell-password {
        margin-top: 4rem;
      }

      body.hello-ident.ident #ia-identification .ident .main-content .container-ident #logincanalnet .grille-ident li .cell-password .field-valid {
        width: 70%;
        margin: auto;
      }

      body.hello-ident.ident #ia-identification .ident .main-content .container-ident #logincanalnet .grille-ident li .cell-password .field-valid #submitIdent {
        width: 100%;
        display: block;
        color: #FFF;
        background-color: #f0767e !important;
        cursor: pointer;
        text-align: center;
        text-transform: uppercase;
        border-radius: 50px;
        font-size: 12px;
        font-weight: bold;
        padding: 14px 30px;
        -webkit-box-shadow: 0px 3px 6px 0 rgba(31, 39, 42, 0.18);
        box-shadow: 0px 3px 6px 0 rgba(31, 39, 42, 0.18);
        -webkit-appearance: none;
        border: none;
      }

      body.hello-ident.ident #ia-identification .ident .main-content .container-ident #logincanalnet .grille-ident li .cell-password .field-valid #submitIdent:disabled:disabled {
        cursor: default;
        opacity: 0.5;
        pointer-events: none;
      }

      body.hello-ident.ident #ia-identification .ident .main-content .container-ident #logincanalnet .grille-ident li #ident-bottom-grid {
        width: calc(131% + 6px);
        margin-left: -15%;
        margin-bottom: -3rem;
        position: absolute;
        left: -5px;
        bottom: -10.7rem;
        padding: 0;
      }

      body.hello-ident.ident #ia-identification .ident .main-content .container-ident #logincanalnet .grille-ident li #ident-bottom-grid .row:nth-child(1) {
        margin: 2rem 0 5rem;
